#!/bin/sh
# Generated by Netinja agent — peer egress policy routing. Do not edit.
set +e
# One apply at a time. wg-quick PostUp and agent start can invoke this
# together; extra copies must return immediately so boot is not stacked.
if command -v flock >/dev/null 2>&1; then
  exec 9>"$0.lock"
  if ! flock -n 9; then
    echo "peer-egress: another apply is running; skipping" >&2
    exit 0
  fi
fi
sysctl -w net.ipv4.ip_forward=1 >/dev/null 2>&1 || true

_iface_ready() {
  ip link show "$1" >/dev/null 2>&1
}

_soften_rp_filter() {
  iface="$1"
  sysctl -w "net.ipv4.conf.${iface}.rp_filter=0" >/dev/null 2>&1 || true
}

_default_for_iface() {
  iface="$1"
  table="$2"
  if ! _iface_ready "$iface"; then
    echo "peer-egress: exit interface missing: $iface (table $table)" >&2
    return 1
  fi
  _soften_rp_filter "$iface"
  via="$(ip -4 route show default 2>/dev/null | awk -v d="$iface" '{for(i=1;i<=NF;i++) if($i=="dev" && $(i+1)==d){for(j=1;j<=NF;j++) if($j=="via"){print $(j+1); exit}}}')"
  if [ -n "$via" ]; then
    ip route replace default via "$via" dev "$iface" table "$table" 2>/dev/null || return 1
  else
    ip route replace default dev "$iface" table "$table" 2>/dev/null || return 1
  fi
}

if _default_for_iface "deutch" 12014; then
  ip rule del from "10.90.68.1/32" lookup 12014 2>/dev/null || true
  ip rule del from "10.90.68.1/32" prohibit 2>/dev/null || true
  ip rule add from "10.90.68.1/32" lookup 12014 pref 19012 2>/dev/null || true
else
  echo "peer-egress: deferred 10.90.68.1/32 -> deutch (interface missing or route failed; keeping existing rule)" >&2
fi

_soften_rp_filter "wg0"

if command -v nft >/dev/null 2>&1; then
  nft add table inet netinja_egress 2>/dev/null || true
  nft add chain inet netinja_egress postrouting "{ type nat hook postrouting priority srcnat; policy accept; }" 2>/dev/null || true
  nft add chain inet netinja_egress forward "{ type filter hook forward priority filter; policy accept; }" 2>/dev/null || true
  nft flush chain inet netinja_egress postrouting 2>/dev/null || true
  nft flush chain inet netinja_egress forward 2>/dev/null || true
  nft add rule inet netinja_egress postrouting oifname "deutch" masquerade comment "netinja-egress-deutch" 2>/dev/null || true
  nft add rule inet netinja_egress forward oifname "deutch" tcp flags syn / syn,rst tcp option maxseg size set rt mtu comment "netinja-egress-deutch-mss" 2>/dev/null || true
  nft add rule inet netinja_egress forward oifname "deutch" accept comment "netinja-egress-deutch-fwd-out" 2>/dev/null || true
  nft add rule inet netinja_egress forward iifname "deutch" ct state related,established accept comment "netinja-egress-deutch-fwd-in" 2>/dev/null || true
  nft add rule inet netinja_egress forward iifname "wg0" tcp flags syn / syn,rst tcp option maxseg size set rt mtu comment "netinja-egress-tunnel-wg0-mss" 2>/dev/null || true
  nft add rule inet netinja_egress forward iifname "wg0" accept comment "netinja-egress-tunnel-wg0-in" 2>/dev/null || true
  nft add rule inet netinja_egress forward oifname "wg0" accept comment "netinja-egress-tunnel-wg0-out" 2>/dev/null || true
  if command -v iptables >/dev/null 2>&1; then
    while iptables -t nat -D POSTROUTING -o "deutch" -j MASQUERADE 2>/dev/null; do :; done
    while iptables -t nat -D POSTROUTING -o "deutch" -m comment --comment "netinja-egress-deutch" -j MASQUERADE 2>/dev/null; do :; done
  fi
  if command -v iptables-legacy >/dev/null 2>&1; then
    while iptables-legacy -t nat -D POSTROUTING -o "deutch" -j MASQUERADE 2>/dev/null; do :; done
    while iptables-legacy -t nat -D POSTROUTING -o "deutch" -m comment --comment "netinja-egress-deutch" -j MASQUERADE 2>/dev/null; do :; done
  fi
elif command -v iptables >/dev/null 2>&1; then
  iptables -t nat -C POSTROUTING -o "deutch" -m comment --comment "netinja-egress-deutch" -j MASQUERADE 2>/dev/null || iptables -t nat -A POSTROUTING -o "deutch" -m comment --comment "netinja-egress-deutch" -j MASQUERADE
  iptables -C FORWARD -o "deutch" -p tcp --tcp-flags SYN,RST SYN -m comment --comment "netinja-egress-deutch-mss" -j TCPMSS --clamp-mss-to-pmtu 2>/dev/null || iptables -I FORWARD 1 -o "deutch" -p tcp --tcp-flags SYN,RST SYN -m comment --comment "netinja-egress-deutch-mss" -j TCPMSS --clamp-mss-to-pmtu
  iptables -C FORWARD -o "deutch" -m comment --comment "netinja-egress-deutch-fwd-out" -j ACCEPT 2>/dev/null || iptables -I FORWARD 1 -o "deutch" -m comment --comment "netinja-egress-deutch-fwd-out" -j ACCEPT
  iptables -C FORWARD -i "deutch" -m state --state RELATED,ESTABLISHED -m comment --comment "netinja-egress-deutch-fwd-in" -j ACCEPT 2>/dev/null || iptables -I FORWARD 1 -i "deutch" -m state --state RELATED,ESTABLISHED -m comment --comment "netinja-egress-deutch-fwd-in" -j ACCEPT
  iptables -C FORWARD -i "wg0" -p tcp --tcp-flags SYN,RST SYN -m comment --comment "netinja-egress-tunnel-wg0-mss" -j TCPMSS --clamp-mss-to-pmtu 2>/dev/null || iptables -I FORWARD 1 -i "wg0" -p tcp --tcp-flags SYN,RST SYN -m comment --comment "netinja-egress-tunnel-wg0-mss" -j TCPMSS --clamp-mss-to-pmtu
  iptables -C FORWARD -i "wg0" -m comment --comment "netinja-egress-tunnel-wg0-in" -j ACCEPT 2>/dev/null || iptables -I FORWARD 1 -i "wg0" -m comment --comment "netinja-egress-tunnel-wg0-in" -j ACCEPT
  iptables -C FORWARD -o "wg0" -m comment --comment "netinja-egress-tunnel-wg0-out" -j ACCEPT 2>/dev/null || iptables -I FORWARD 1 -o "wg0" -m comment --comment "netinja-egress-tunnel-wg0-out" -j ACCEPT
elif command -v iptables-legacy >/dev/null 2>&1; then
  iptables-legacy -t nat -C POSTROUTING -o "deutch" -m comment --comment "netinja-egress-deutch" -j MASQUERADE 2>/dev/null || iptables-legacy -t nat -A POSTROUTING -o "deutch" -m comment --comment "netinja-egress-deutch" -j MASQUERADE
  iptables-legacy -C FORWARD -o "deutch" -p tcp --tcp-flags SYN,RST SYN -m comment --comment "netinja-egress-deutch-mss" -j TCPMSS --clamp-mss-to-pmtu 2>/dev/null || iptables-legacy -I FORWARD 1 -o "deutch" -p tcp --tcp-flags SYN,RST SYN -m comment --comment "netinja-egress-deutch-mss" -j TCPMSS --clamp-mss-to-pmtu
  iptables-legacy -C FORWARD -o "deutch" -m comment --comment "netinja-egress-deutch-fwd-out" -j ACCEPT 2>/dev/null || iptables-legacy -I FORWARD 1 -o "deutch" -m comment --comment "netinja-egress-deutch-fwd-out" -j ACCEPT
  iptables-legacy -C FORWARD -i "deutch" -m state --state RELATED,ESTABLISHED -m comment --comment "netinja-egress-deutch-fwd-in" -j ACCEPT 2>/dev/null || iptables-legacy -I FORWARD 1 -i "deutch" -m state --state RELATED,ESTABLISHED -m comment --comment "netinja-egress-deutch-fwd-in" -j ACCEPT
  iptables-legacy -C FORWARD -i "wg0" -p tcp --tcp-flags SYN,RST SYN -m comment --comment "netinja-egress-tunnel-wg0-mss" -j TCPMSS --clamp-mss-to-pmtu 2>/dev/null || iptables-legacy -I FORWARD 1 -i "wg0" -p tcp --tcp-flags SYN,RST SYN -m comment --comment "netinja-egress-tunnel-wg0-mss" -j TCPMSS --clamp-mss-to-pmtu
  iptables-legacy -C FORWARD -i "wg0" -m comment --comment "netinja-egress-tunnel-wg0-in" -j ACCEPT 2>/dev/null || iptables-legacy -I FORWARD 1 -i "wg0" -m comment --comment "netinja-egress-tunnel-wg0-in" -j ACCEPT
  iptables-legacy -C FORWARD -o "wg0" -m comment --comment "netinja-egress-tunnel-wg0-out" -j ACCEPT 2>/dev/null || iptables-legacy -I FORWARD 1 -o "wg0" -m comment --comment "netinja-egress-tunnel-wg0-out" -j ACCEPT
fi

exit 0
